mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { mkdtemp, readFile, writeFile, readdir, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
const run = promisify(execFile);
const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g3-1/bot.mjs';
const base = await mkdtemp(path.join(tmpdir(), 'bot-'));
const dir = path.join(base, 'does', 'not', 'exist');   // must be created
process.env.STATE_DIR = dir;
const bot = await import(BOT + '?t=' + Date.now());
const now = new Date();
const ok = [];
const check = (name, fn) => ok.push([name, fn]);

// fresh address: no opt-in -> marketing denied, receipt allowed
let r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, false); assert.match(r.reason, /opt-in/);
r = await bot.mayEmail('<EMAIL>', 'receipt', now);
assert.equal(r.allowed, true);

// opt-in then marketing allowed, with messy casing/spaces
await bot.resubscribe('  <EMAIL> ');
r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, true, r.reason);

// unsubscribe via different spelling blocks marketing, not receipts
await bot.unsubscribe('<EMAIL>\n');
r = await bot.mayEmail(' <EMAIL> ', 'marketing', now);
assert.equal(r.allowed, false); assert.match(r.reason, /unsubscribed/);
r = await bot.mayEmail('<EMAIL>', 'receipt', now);
assert.equal(r.allowed, true);

// resubscribe after deliberate signup restores marketing
await bot.resubscribe('<EMAIL>');
r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, true);

// gmail dot/googlemail aliasing maps to same record
await bot.unsubscribe('<EMAIL>');
r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, false);

// invalid addresses
r = await bot.mayEmail('not an email', 'marketing', now);
assert.equal(r.allowed, false); assert.match(r.reason, /not a valid/);
r = await bot.mayEmail('<EMAIL>', 'sms', now);
assert.equal(r.allowed, false);
await assert.rejects(bot.unsubscribe(''), TypeError);
await assert.rejects(bot.mayEmail('<EMAIL>', 'marketing', new Date('x')), TypeError);

// torn trailing record after valid opt-in -> fail closed
await bot.resubscribe('<EMAIL>');
const shards = await readdir(path.join(dir, 'suppression'));
const tornFile = await (async () => {
  for (const f of shards) {
    const t = await readFile(path.join(dir, 'suppression', f), 'utf8');
    if (t.includes('resubscribe')) { const { createHash } = await import('node:crypto');
      if (createHash('sha256').update('<EMAIL>').digest('hex') + '.log' === f) return path.join(dir,'suppression',f); }
  }
})();
await writeFile(tornFile, (await readFile(tornFile, 'utf8')) + '\n{"ev":"unsub');
r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, false); assert.match(r.reason, /damaged/);
await bot.resubscribe('<EMAIL>');
r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, true);

// concurrent writers in separate processes
const script = `import('${BOT}').then(async b => { for (let i=0;i<40;i++) await b.unsubscribe('<EMAIL>'); await b.resubscribe('<EMAIL>'); })`;
await Promise.all([1,2,3,4,5].map(() => run(process.execPath, ['--input-type=module', '-e', script], { env: { ...process.env, STATE_DIR: dir } })));
const raceFile = path.join(dir, 'suppression', (await import('node:crypto')).createHash('sha256').update('<EMAIL>').digest('hex') + '.log');
const lines = (await readFile(raceFile, 'utf8')).split('\n').filter(Boolean);
assert.equal(lines.length, 5 * 41);
assert.ok(lines.every(l => { try { JSON.parse(l); return true; } catch { return false; } }));
r = await bot.mayEmail('<EMAIL>', 'marketing', now);
assert.equal(r.allowed, true, 'last appended event wins');

// new process sees the state written by earlier processes
const out = await run(process.execPath, ['--input-type=module', '-e', `import('${BOT}').then(async b => console.log(JSON.stringify(await b.mayEmail('<EMAIL>','marketing',new Date()))))`], { env: { ...process.env, STATE_DIR: dir } });
assert.equal(JSON.parse(out.stdout).allowed, true);

for (const [n] of ok) {}
await rm(base, { recursive: true, force: true });
console.log('ALL CHECKS PASSED');
EOF
cd /tmp/bot-test && node test.mjs
